#include "pch.h"
#include <vector>



extern "C" __declspec(dllexport) bool AddNoise(uint8_t* piksele, int szerokosc, int wysokosc, int stride) {
    //sample func generated by ai

    for (int y = 0; y < wysokosc; ++y) {
        uint8_t* wiersz = piksele + (y * stride);
        for (int x = 0; x < szerokosc * 3; ++x) { // *3 dla 24bpp, *4 dla 32bpp
            wiersz[x] = 255 - wiersz[x];
        }
    }
    return true;
}
